const zlib = require("zlib");
const { decode, generateQRData } = require("../src");

describe("decode", () => {
  test("decode simple base45 string", () => {
    expect(decode("NCFKVPV0QSIP600GP5L0")).toBe("hello");
  });

  test("decode CBOR encoded QR data", () => {
    expect(decode("NCF3QBXJA5NJRCOC004 QN4")).toBe('{"temp":15}');
  });

  test("decode CBOR array QR", () => {
    const data = '[{"a":1},{"b":2}]';
    const encoded = generateQRData(data);
    expect(decode(encoded)).toBe(data);
  });

  test("decode handles null values", () => {
    const encoded = generateQRData(JSON.stringify({ key: null }));
    expect(decode(encoded)).toBe('{"key":null}');
  });

  test("decode handles booleans", () => {
    const encoded = generateQRData(JSON.stringify({ a: true, b: false }));
    expect(JSON.parse(decode(encoded))).toStrictEqual({ a: true, b: false });
  });

  test("decode returns text when CBOR fails", () => {
    const encoded = generateQRData("hello");
    expect(decode(encoded)).toBe("hello");
  });

  test("decode throws on invalid base45", () => {
    expect(() => decode("^1")).toThrow();
  });

  test("decode cwt data", () => {
    const cwtData =
      "";
    const qrData =
      "NCFO-MEC8KODJR19H2-MM Q98B0338G6J2O7$PT2PK75T1:BYHR3S4PU4OIQC.LVWU+9HL:T:UJ4-9:WTRWVVB2$VQR 66IPA+3DALB2208G%1U-VFJ1NK08-9Q%UB36N2ZUQ*O/QFSOVENQ60WXQP/9F:W9VGVA6O3BV*YNO-AA*R-ZUL%3UXE++3RXSYI5-72+-Q5RREZ6EFP-6DZNPLZF*:FZ6HVUAAOUATKXGL4J6XUL2232FD1BVPYIQ4MVAM.8I69OYARY/5A+QN%B+-9T:QZWV47W+6K-B4L.M58TEF9 M4UCL8V0XHNBHH%0P+BJ6IBRDV.BTE*IPC5Q2ARR158MT:UP2AIXHSTI6L3V8EI0RQ*2$D9FVB2P7SC7TBBY9LG-Q-%LJ3RHRS91F+536SRU042NB YH4QH-W7JAPN.2DEQ7G0BJ9X.B4CO OD5HI4+054Q%NM%DV50D255PSS2J48KOJ29GCBQ73MPC4*P85D0.PNZ5:/79VPK.EGZP3H7/JU69I%Y719H3R5$4V$4U.JJ1NC*GFIX4T:JQOV0HH6XDF4FC.FOV58DTMP389AAH9*PPV+AJ5NKRNZVNM/LLPFW2JA0IZJJS+7LR5%IH4KH.60F2VZTMD.7WQT 1A9H3MGNF 71RC7DCVW5+$P 7TPK8 L40RLRP7+NG1AOW9AKTSE-QPACBGEWT1-9K-CHU%VU.VDVU";
    const decodedData = decode(qrData);
    expect(decodedData).toStrictEqual(cwtData);
  });

test("decode handles Brotli compressed input", () => {
  const base45 = require("base45-web");

  const payload = "hello brotli";
  const brotliCompressed = zlib.brotliCompressSync(Buffer.from(payload));
  const base45Encoded = base45.encode(Buffer.from(brotliCompressed));

  expect(decode(base45Encoded)).toBe(payload);
});
});